USE CakesDB; GO   CREATE LOGIN manager_login WITH PASSWORD = 'Manager123!'; CREATE LOGIN chef_login WITH PASSWORD = 'Chef123!'; CREATE LOGIN accountant_login WITH PASSWORD = 'Account123!'; CREATE LOGIN client_login WITH PASSWORD = 'Client123!'; GO  -- Перевірка логінів SELECT name FROM sys.server_principals WHERE type_desc = 'SQL_LOGIN';  CREATE USER manager_user FOR LOGIN manager_login; CREATE USER chef_user FOR LOGIN chef_login; CREATE USER accountant_user FOR LOGIN accountant_login; CREATE USER client_user FOR LOGIN client_login; GO  -- Перевірка користувачів SELECT name FROM sys.database_principals WHERE type = 'S';  CREATE ROLE manager_role; CREATE ROLE chef_role; CREATE ROLE accountant_role; GO  -- Перевірка ролей SELECT name FROM sys.database_principals WHERE type = 'R';  GRANT SELECT, INSERT, UPDATE ON Orders TO manager_role; GRANT SELECT ON Clients TO manager_role;   GRANT SELECT ON Cakes TO chef_role; GRANT SELECT ON Recipe TO chef_role; GRANT SELECT ON Ingredients TO chef_role;   GRANT SELECT, INSERT ON Payments TO accountant_role; GRANT SELECT ON Orders TO accountant_role; GO   ALTER ROLE manager_role ADD MEMBER manager_user; ALTER ROLE chef_role ADD MEMBER chef_user; ALTER ROLE accountant_role ADD MEMBER accountant_user; GO   REVOKE SELECT ON Orders FROM manager_role; GO   ALTER ROLE chef_role DROP MEMBER chef_user; GO  DROP ROLE chef_role; GO  DROP USER chef_user; GO  DROP LOGIN chef_login; GO  --Перевірки привілеїв   EXECUTE AS USER = 'chef_user'; SELECT * FROM Recipe; REVERT;  EXECUTE AS USER = 'client_user'; SELECT * FROM Recipe; REVERT;  EXECUTE AS USER = 'accountant_user'; INSERT INTO Payments (payment_number, payment_date, amount, payment_type, order_id) VALUES (900, GETDATE(), 200, 'карта', 1); REVERT;  EXECUTE AS USER = 'client_user'; INSERT INTO Payments (payment_number, payment_date, amount, payment_type, order_id) VALUES (901, GETDATE(), 200, 'card', 1); REVERT;  EXECUTE AS USER = 'manager_user'; UPDATE Orders SET status = 'in_progress' WHERE id = 2; REVERT;  EXECUTE AS USER = 'chef_user'; UPDATE Orders SET status = 'done' WHERE id = 3; REVERT;  